<script setup lang="ts">
import {computed,ref,nextTick} from 'vue'
import {api} from '../api'
import {usePolling} from '../usePolling'
import {useMarketStore} from '../store'
import {number,time} from '../format'
import {labelNames,percentage} from '../onchain'
import type {ChainView,ChainSample,ChainBinding,AddressLabel} from '../onchain'
import PageIntro from '../components/PageIntro.vue'
import StatCard from '../components/StatCard.vue'
import FeatureValue from '../components/FeatureValue.vue'
const rows=ref<ChainView[]>([]);const status=ref<{apiKeyConfigured:boolean;settings:{watchMinutes:number;candidateHours:number;dayRequestBudget:number;weekRequestBudget:number}}|null>(null)
const store=useMarketStore();const selectedId=ref<number|null>(null);const history=ref<ChainSample[]>([]);const busy=ref(false);const actionError=ref('');const message=ref('')
const editor=ref(false);const query=ref('ARIA');const assetId=ref<number|null>(null);const chain=ref('bsc');const contract=ref('');const coinId=ref('');const enabled=ref(true);const confirm=ref(false);const revision=ref(0)
const labelAddress=ref('');const labelChain=ref('bsc');const labelType=ref(0);const labelEvidence=ref('');const labelConfirm=ref(false);const labelRevision=ref(0)
async function load(signal?:AbortSignal){const [r,s]=await Promise.all([api<ChainView[]>('/api/onchain',{signal}),api<typeof status.value>('/api/onchain/status',{signal})]);rows.value=r;status.value=s;await store.refresh(signal)}
const {error,refresh}=usePolling(signal=>load(signal),15000)
const current=computed(()=>rows.value.find(r=>r.binding.assetId===selectedId.value));const selected=computed(()=>current.value??rows.value[0]);
const matches=computed(()=>store.assets.filter(a=>a.instrument.symbol.includes(query.value.trim().toUpperCase())).slice(0,15))
const name=(id:number)=>store.assets.find(a=>a.instrument.assetId===id)?.instrument.symbol??`Asset ${id}`
const providerHealth=computed(()=>store.health.filter(h=>h.health.name==='OnChain'))
function edit(id:number){if(busy.value)return;assetId.value=id;const b=rows.value.find(r=>r.binding.assetId===id)?.binding;chain.value=b?.chain??'bsc';contract.value=b?.contractAddress??'';coinId.value=b?.coinGeckoId??'';enabled.value=b?.enabled??true;revision.value=b?.revision??0;confirm.value=false;editor.value=true;actionError.value=''}
let historyRequest=0
async function detail(id:number){labelAddress.value="";selectedId.value=id;history.value=[];const request=++historyRequest;try{const h=await api<ChainSample[]>(`/api/onchain/${id}/history?limit=60`);if(request===historyRequest)history.value=h}catch(e){if(request===historyRequest)actionError.value=String(e)}}
async function editLabel(address:string){if(busy.value||!selected.value)return;labelChain.value=selected.value.binding.chain;labelAddress.value=address;const l=selected.value.features.labels.find(l=>l.address.toLowerCase()===address.toLowerCase());labelType.value=l?.type??0;labelEvidence.value=l?.evidenceUrl??'';labelRevision.value=l?.revision??0;labelConfirm.value=false;message.value='';await nextTick();document.getElementById('chain-label-editor')?.scrollIntoView({behavior:'smooth'})}
function invalidateLabel(){labelConfirm.value=false}
async function run(work:()=>Promise<void>){if(busy.value)return;busy.value=true;actionError.value='';try{await work()}catch(e){actionError.value=e instanceof Error?e.message:'操作失败'}finally{busy.value=false}}
const saveBinding=()=>run(async()=>{if(assetId.value===null)return;await api<ChainBinding>(`/api/onchain/${assetId.value}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({chain:chain.value,contractAddress:contract.value.trim(),coinGeckoId:coinId.value.trim(),enabled:enabled.value,expectedRevision:revision.value,confirmIdentity:confirm.value})});editor.value=false;await load();message.value='链上身份已保存；后台会按预算与调度采集，不立即重复请求。'})
const saveLabel=()=>run(async()=>{await api<AddressLabel>('/api/onchain/labels',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({chain:labelChain.value,address:labelAddress.value,type:Number(labelType.value),evidenceUrl:labelEvidence.value.trim(),expectedRevision:labelRevision.value,confirmEvidence:labelConfirm.value})});await load();labelAddress.value='';message.value='标签已保存；Unknown 可撤销已核对分类，历史修改保留。'})
const sourceLink=(r:ChainView)=>r.binding.chain==='bsc'?`https://binplorer.com/token/${r.binding.contractAddress}`:r.binding.chain==='ethereum'?`https://ethplorer.io/address/${r.binding.contractAddress}`:'https://gopluslabs.io/'
const labelFor=(address:string)=>selected.value?.features.labels.find(l=>l.address.toLowerCase()===address.toLowerCase())
</script>
<template><p><RouterLink to="/flows">查看链上资金流与主要地址核验 →</RouterLink></p><PageIntro eyebrow="ONCHAIN · BSC / EVM" title="看清分布，再判断集中。" description="人数、原始排名与分类口径分别展示，不把大地址直接当成项目方。"><button class="replay-action" @click="refresh">读取最新缓存</button></PageIntro><p v-if="error||actionError" class="radar-notice" role="alert">{{actionError||error}}</p><p v-if="message" class="radar-notice" role="status">{{message}}</p><p class="radar-notice">BSC / Ethereum 使用 Binplorer / Ethplorer Top100；其他支持的 EVM 链使用 GoPlus Top10。缺少覆盖时 Top25/50/100 保持 Unknown。AdjustedTop10 不等于项目方持仓，也不证明低风险。</p>
<div class="stats"><StatCard label="链上观察资产" :value="rows.length" :foot="`自选默认 ${status?.settings.watchMinutes??30} 分钟 · 其他 ${status?.settings.candidateHours??6} 小时`"/><StatCard label="身份已核对" :value="rows.filter(r=>r.features.trustedIdentity).length" foot="与当前目录中的链和地址一致"/><StatCard label="Top100 数据可用" :value="rows.filter(r=>r.features.rawTopPercent['100']?.status===0).length" foot="同一提供者、同一链合约的快照"/><StatCard label="分类覆盖通过" :value="rows.filter(r=>r.features.concentrationUsable).length" foot="已核对标签余额覆盖至少 50% 才进入评分"/></div>
<div class="provider-grid"><div v-for="h in providerHealth" :key="h.health.name" class="provider"><div><b>{{h.health.name}}</b><span class="health" :class="h.status.toLowerCase()">{{h.status}}</span></div><span>{{time(h.health.lastSuccess)}}</span><p v-if="h.health.error" class="provider-error">{{h.health.error}}</p></div></div><p class="refresh-text">{{status?.apiKeyConfigured?'已配置服务端索引器 Key':'使用公开开发 freekey，长期运行可在本机配置 PULLET_EXPLORER_API_KEY'}} · 请求预算每日 {{status?.settings.dayRequestBudget}} / 每周 {{status?.settings.weekRequestBudget}}。密钥不在页面输入。</p>
<div class="section-heading"><h2>链与合约身份</h2></div><div class="market-panel"><div class="toolbar"><label class="search"><input v-model="query" aria-label="搜索链上资产" placeholder="本地交易所合约"></label><span>最多 15 个匹配</span></div><div class="toolbar"><button v-for="m in matches" :key="m.instrument.assetId" class="text-button" @click="edit(m.instrument.assetId)">{{m.instrument.symbol}} · 配置</button></div></div>
<section v-if="editor" class="detail"><div class="section-heading"><h2>{{assetId===null?'':name(assetId)}} · 主链配置</h2><button class="text-button" :disabled="busy" @click="editor=false">取消 ×</button></div><p>每个资产配置一个主链；链与地址必须符合所选 CoinGecko ID。此配置不自动确认市值映射或 Gate 身份。</p><div class="mapping-form"><label>CoinGecko ID<input v-model="coinId" aria-label="链上 CoinGecko ID" @input="confirm=false"></label><label>链<select v-model="chain" aria-label="选择链上网络" @change="confirm=false"><option v-for="n in ['bsc','ethereum','base','arbitrum','polygon']" :key="n">{{n}}</option></select></label><label class="full-width">代币合约<input v-model="contract" aria-label="链上代币合约" @input="confirm=false"></label></div><label class="checkbox"><input v-model="enabled" type="checkbox">启用后台采集</label><label class="checkbox"><input v-model="confirm" type="checkbox" aria-label="确认链上资产身份">我已核对本地资产、唯一 ID、链和完整合约身份。</label><button class="replay-action" :disabled="busy||!confirm" @click="saveBinding">保存链上配置</button><RouterLink :to="{path:'/mappings',query:{symbol:assetId===null?'':name(assetId)}}"> 检查目录映射 →</RouterLink></section>
<div class="section-heading radar-heading"><h2>持币人数与分布</h2></div><div class="market-panel table-scroll"><table><thead><tr><th>资产 / 链</th><th>人数</th><th>约 24h 人数变化</th><th>Top10</th><th>Top25</th><th>Top50</th><th>Top100</th><th>AdjustedTop10</th><th>分类覆盖</th><th>来源</th></tr></thead><tbody><tr v-for="r in rows" :key="r.binding.assetId" @click="detail(r.binding.assetId)"><td>{{name(r.binding.assetId)}}<small>{{r.binding.chain}} · {{r.binding.enabled?'启用':'停用'}}</small></td><td><FeatureValue :feature="r.features.holderCount"/></td><td><FeatureValue :feature="r.features.holderChange24h"/> / <FeatureValue :feature="r.features.holderChange24hPercent" suffix="%"/></td><td v-for="n in [10,25,50,100]" :key="n"><FeatureValue :feature="r.features.rawTopPercent[String(n)]" suffix="%"/></td><td><FeatureValue :feature="r.features.adjustedTop10Percent" suffix="%"/></td><td>{{number(r.features.classificationCoveragePercent,1)}}%<small>{{r.features.concentrationUsable?'可用于评分':'仅参考，待核对标签'}}</small></td><td>{{r.features.provider??'等待采集'}}<small>{{r.features.returnedHolders}} 个地址 · 点击详情</small></td></tr><tr v-if="!rows.length"><td colspan="10" class="empty">目录和本地资产加载后会建立 ARIA 的参考合约，或手动配置其他资产。</td></tr></tbody></table></div>
<section v-if="selected" class="detail"><div class="section-heading"><h2>{{name(selected.binding.assetId)}} · 原始地址与证据</h2><a :href="sourceLink(selected)" target="_blank" rel="noopener noreferrer">{{selected.features.provider??'索引器'}} 数据源 ↗</a></div><p>{{selected.binding.chain}} · {{selected.binding.contractAddress}} · {{selected.binding.coinGeckoId}}</p><p>{{selected.binding.verification}}</p><p v-for="url in selected.binding.evidenceUrls" :key="url"><a :href="url" target="_blank" rel="noopener noreferrer">{{url}}</a></p><p>源时间 {{time(selected.sample?.sourceTime)}} · 接收 {{time(selected.sample?.receivedTime)}} · 下次尝试 {{time(selected.attempt?.nextAttempt)}}</p><p v-if="selected.attempt?.error" class="radar-notice">{{selected.attempt.error}}</p><p v-for="c in selected.features.caveats" :key="c">{{c}}</p><div class="detail-grid"><div><span>已观测 Exchange 余额占比下界</span><strong><FeatureValue :feature="selected.features.observedExchangePercent" suffix="%"/></strong></div><div><span>已观测 Project / Team / Investor / Treasury 占比下界</span><strong><FeatureValue :feature="selected.features.observedProjectPercent" suffix="%"/></strong></div></div>
<details class="detail"><summary>展开持币地址列表与标签核对（{{selected.sample?.holders.length??0}} 个）</summary><div class="section-heading"><h2>Top {{selected.sample?.holders.length??0}} 地址</h2><span class="refresh-text">原始余额以最小单位字符串展示，不用浏览器浮点数换算</span></div><div class="table-scroll"><table><thead><tr><th>排名</th><th>地址</th><th>供应量占比</th><th>原始余额</th><th>核对标签 / 提供者线索</th><th>操作</th></tr></thead><tbody><tr v-for="(h,index) in selected.sample?.holders??[]" :key="h.address"><td>{{index+1}}</td><td class="decision-reason">{{h.address}}</td><td>{{percentage(h.percent)}}</td><td class="decision-reason">{{h.rawBalance||'未提供原始最小单位余额'}}</td><td>{{labelNames[labelFor(h.address)?.type??0]}}<small>{{h.reportedTag||'未提供标签线索'}}</small></td><td><button class="text-button" @click="editLabel(h.address)">核对标签</button></td></tr></tbody></table></div>
<section v-if="labelAddress" id="chain-label-editor" class="detail"><h3>{{labelChain}} · 地址标签</h3><p>{{labelAddress}} · 编辑版本 {{labelRevision}}</p><div class="mapping-form"><label>分类<select v-model="labelType" aria-label="选择地址标签" @change="invalidateLabel"><option v-for="(n,index) in labelNames" :key="n" :value="index">{{n}}</option></select></label><label>证据 HTTPS 链接<input v-model="labelEvidence" aria-label="地址标签证据" @input="invalidateLabel"></label></div><label class="checkbox"><input v-model="labelConfirm" type="checkbox" aria-label="确认地址标签证据">我已核对分类依据。LP / Bridge / Burn 会影响调整后排名；Contract 不会自动排除。</label><button class="replay-action" :disabled="busy||Number(labelType)!==0&&!labelConfirm" @click="saveLabel">保存地址标签</button><button class="text-button" :disabled="busy" @click="labelAddress=''">取消标签编辑</button></section>
</details><div class="section-heading radar-heading"><h2>人数历史 · 本地观测</h2><button class="text-button" @click="detail(selected.binding.assetId)">读取历史</button></div><div class="table-scroll"><table><thead><tr><th>源时间</th><th>提供者</th><th>人数</th><th>返回地址 / 请求范围</th></tr></thead><tbody><tr v-for="h in history" :key="h.id"><td>{{time(h.sourceTime)}}</td><td>{{h.provider}}</td><td>{{h.holderCount??'Unknown'}}</td><td>{{h.holders.length}} / {{h.requestedCount}}</td></tr></tbody></table></div><RouterLink to="/watchtower">查看 WatchTower →</RouterLink> · <RouterLink to="/speculative">查看妖币雷达 →</RouterLink></section>
</template>


<style scoped>.detail p,.detail a{overflow-wrap:anywhere}</style>
